import {ensureFacts,startFact,startFactsMix,currentFact,submitFact,setFactMethod,showFactModel,revealFact,stepFactModel,finishFact,advanceFacts,setFactsRow,factsSummary,factPairsShown,splitFact,factsRecordLimit} from './facts-core.mjs';
import {numericAnswer} from './core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const methodLabels={recalled:'Reported recall',worked:'Worked it out',counting:'Counted',together:'Worked together'};
const action=(id,label,style='secondary',extra='')=>`<button type="button" class="${style}" data-facts-action="${id}" ${extra}>${label}</button>`;
const title=(heading,body)=>`<header class="facts-heading"><a href="#home" class="back">← Take a break</a><p class="facts-eyebrow">Every patch is open</p><h1>${heading}</h1><p>${body}</p></header>`;
const triedLabel=r=>!r?'not tried yet':r.status!=='recorded'?'skipped for now':r.reportedRecall?'remembered it':r.correct===true?(r.supported?'tried with help':'tried'):'tried, worth another look';
const resultLabel=r=>!r?'No retained answer observation':r.status!=='recorded'?'Left for now; no recall claim':r.reportedRecall?'Reported recall on this visit':r.correct===true?(r.supported?'Found an answer with support':r.method?methodLabels[r.method]:'Correct answer; method not observed'):'An attempt to explore again';
function factButton(a,b,summary){
 const r=summary.latest,style=!r?'unknown':r.status!=='recorded'?'unexplored':r.reportedRecall?'recalled':r.supported?'supported':'explored';
 return `<button type="button" class="facts-cell ${style}" data-facts-pair="${a},${b}" aria-label="${a} times ${b}, ${esc(triedLabel(r))}"><span>${a} × ${b}</span><span class="facts-cell-mark" aria-hidden="true">${!r?'·':r.status!=='recorded'?'↩':r.reportedRecall?'★':r.supported?'＋':'○'}</span></button>`;
}
function matrix(state){
 const summaries=factsSummary(state),f=state.facts,row=f?.row||1;
 const cell=(a,b)=>factButton(a,b,summaries[(a-1)*12+b-1]||{latest:null,days:[]});
 return `<div data-facts-view class="facts-view">${title('The multiplication garden','Choose any fact from 1 × 1 to 12 × 12, or try six different facts. Pictures, thinking time, and leaving something for later are welcome.')}<section class="facts-garden-intro"><div class="facts-sprout" aria-hidden="true"><span>×</span></div><div><h2>A whole garden of equal groups</h2><p>Every square is a little bed. Some hold one row, and some hold twelve. Pick any square to try a fact.</p><div class="facts-controls">${action('mixed','Try six mixed facts','primary')}${f?.current?'<a class="secondary" href="#facts/play">Return to the current practice visit</a>':''}${hearButton('Every square is a little bed. Some hold one row, and some hold twelve. Pick any square to try a fact.','Hear the garden invitation')}</div></div></section><section class="facts-row-picker"><label for="facts-row">Choose a row for a smaller view</label><select id="facts-row" data-facts-row>${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${row===i+1?'selected':''}>${i+1} ${i===0?'group':'groups'}</option>`).join('')}</select><div class="facts-row-options" role="group" aria-label="Facts with ${row} groups">${Array.from({length:12},(_,i)=>cell(row,i+1)).join('')}</div></section><section class="facts-map"><h2>All twelve rows</h2><p id="facts-map-help" class="tiny">Scroll inside the table to see every column. Use the arrow keys to move around the table.</p><div class="facts-table-window" tabindex="0" role="region" aria-label="All 144 ordered multiplication facts; horizontally scrollable table" aria-describedby="facts-map-help"><table class="facts-table"><caption>Each row tells how many groups. Each column tells how many in each group.</caption><thead><tr><th scope="col"><span aria-hidden="true">Groups ↓<br>In each →</span><span class="sr-only">Groups down, number in each across</span></th>${Array.from({length:12},(_,i)=>`<th scope="col">${i+1}</th>`).join('')}</tr></thead><tbody>${Array.from({length:12},(_,i)=>`<tr><th scope="row">${i+1}</th>${Array.from({length:12},(_,j)=>`<td>${cell(i+1,j+1)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="facts-legend"><span><span aria-hidden="true">·</span> Not tried yet</span><span><span aria-hidden="true">↩</span> Skipped for now</span><span><span aria-hidden="true">＋</span> Tried with help</span><span><span aria-hidden="true">○</span> Tried</span><span><span aria-hidden="true">★</span> Remembered it</span></p><details class="grownup-note"><summary>For grown-ups</summary><p class="tiny">Each ordered fact has its own square. Answering one does not fill in its reverse. Squares show questions only, never answers. The marks are practice observations: “Remembered it” means reported recall on one visit. One answer does not establish lasting fluency or mastery.</p></details></section><div class="facts-destinations"><a href="#cafe">Use equal groups at the café</a><a href="#practice">Visit the original small practice sets</a><a href="#notes">Grown-up notes</a></div></div>`;
}
function splitText(d,answer=false){
 const parts=splitFact(d.a,d.b);if(parts.length===1)return `${d.a} × ${d.b}${answer?' = '+d.a*d.b:''}: one group of ${d.b}.`;
 const [p,q]=parts;
 return answer?`${d.a} × ${d.b} = ${d.a*d.b}. ${p[0]} × ${p[1]} = ${p[0]*p[1]}, and ${q[0]} × ${q[1]} = ${q[0]*q[1]}. Add the parts: ${p[0]*p[1]} + ${q[0]*q[1]} = ${d.a*d.b}.`:`Split ${d.a} rows into ${p[0]} and ${q[0]} rows. Work with ${p[0]} × ${p[1]} and ${q[0]} × ${q[1]}, then add their totals.`;
}
function model(d){
 if(!d.model)return '';
 return `<section class="facts-model" aria-labelledby="facts-model-title"><h3 id="facts-model-title" tabindex="-1">One equal group at a time</h3><p>${d.a} ${d.a===1?'group':'groups'}, with ${d.b} in each. Every row has the same number.</p><div class="facts-controls" role="group" aria-label="Choose a way to picture equal groups">${action('array','An array',`method ${d.modelMode==='array'?'selected':''}`,`aria-pressed="${d.modelMode==='array'}"`)}${action('groups','Separate groups',`method ${d.modelMode==='groups'?'selected':''}`,`aria-pressed="${d.modelMode==='groups'}"`)}</div><div class="facts-picture ${d.modelMode==='groups'?'facts-picture-groups':''}" role="img" aria-label="${d.a} rows with ${d.b} counters in each; ${d.steps} rows counted">${Array.from({length:d.a},(_,i)=>`<div class="facts-picture-row ${i<d.steps?'counted':''}"><span class="facts-row-number">${i+1}</span><div class="facts-row-counters" style="--facts-cols:${d.b}">${'<span class="facts-counter" aria-hidden="true"></span>'.repeat(d.b)}</div><span class="facts-row-text">${d.b} in this ${d.modelMode==='groups'?'group':'row'}</span></div>`).join('')}</div><p class="facts-counted" aria-live="polite">${d.steps} ${d.steps===1?'row':'rows'} counted: ${d.steps*d.b} counters.</p><div class="facts-controls">${action('step','Count the next row','secondary',d.steps===d.a?'disabled':'')}${action('recount','Count again','text-button')}</div><section class="facts-split"><h4>Try useful parts</h4><p>${splitText(d)}</p>${hearButton(splitText(d),'Hear the split')}</section></section>`;
}
function methodView(d){
 return `<fieldset class="facts-method"><legend>How did you find it? (You can skip this.)</legend><p class="tiny">Choose together.</p><div class="facts-method-options">${[['recalled','I recalled it'],['worked','I worked it out'],['counting','I counted'],['together','We worked together']].map(([id,label])=>`<button type="button" data-facts-method="${id}" class="method ${d.method===id?'selected':''}" aria-pressed="${d.method===id}">${label}</button>`).join('')}</div>${d.method?action('clear-method','Skip this','text-button'):''}</fieldset>`;
}
function practice(state){
 const f=state.facts,x=f?.current,d=currentFact(state);if(!x||!d?.opened)return matrix(state);
 const correct=d.attempts.at(-1)?.correct===true,record=f.observations.find(r=>r.id===`${x.id}:${x.index}`);
 if(d.recorded||x.finished)return `<div data-facts-view class="facts-view">${title('Nice place to rest.',`${d.a} × ${d.b} is done for now.`)}<section class="facts-practice facts-pause-sheet"><p class="facts-eyebrow">${x.finished?'This visit is done':'Saved'}</p><h2 id="facts-question-title" tabindex="-1">${d.a} × ${d.b}</h2><div class="facts-controls">${!x.finished?action('next','Try the next fact','primary'):action('mixed','Try another six-fact visit','primary')}<a class="secondary" href="#facts">Choose any garden fact</a><a class="text-button" href="#home">Take a break</a></div><details class="grownup-note"><summary>For grown-ups</summary><p class="tiny">${esc(resultLabel(record))}.</p>${record?.reportedRecall?'<p class="tiny">Reported recall means a correct first attempt, explicit reported recall, and no model or reveal on this question. It does not establish enduring fluency.</p>':''}<p class="tiny">This practice visit is a few observations, and it is no verdict about what a child knows. Methods and help stay attached to their original question. No other fact is marked learned.</p></details></section></div>`;
 const prompt=`What is ${d.a} times ${d.b}?`;
 return `<div data-facts-view class="facts-view">${title('Think in equal groups','A little picture, a familiar part, or a number you recall: you can choose a way in.')}<a class="facts-map-link" href="#facts">Back to all facts (this one will wait)</a><article class="facts-practice"><div class="facts-visit-label"><span>${x.mode==='mixed'?`Fact ${x.index+1} of 6 in this visit`:'Your chosen fact'}</span><span>Practice, at your pace</span></div><h2 id="facts-question-title" tabindex="-1">What is ${d.a} × ${d.b}?</h2>${hearButton(prompt,'Hear the question')}<p>${d.a} ${d.a===1?'group':'groups'}, with ${d.b} in each group.</p>${!correct?`<form data-facts-answer-form novalidate><label for="facts-answer">Your number</label><div class="facts-answer-line"><input id="facts-answer" type="text" inputmode="numeric" maxlength="3" autocomplete="off" value="${esc(d.input)}" aria-describedby="facts-error"><button type="submit" class="primary">Try my answer</button></div><p id="facts-error" data-facts-error role="alert"></p></form>`:''}<div class="facts-feedback" id="facts-feedback" tabindex="-1" aria-live="polite">${correct?'<p>That number fits these equal groups. You can describe your method if you like.</p>':d.attempts.length?'<p>Let’s take another look at these groups. Try a new number, open a picture, or skip it for now.</p>':''}</div>${correct?methodView(d):''}<div class="facts-controls">${!d.model?action('array','Open an array picture','secondary'):''}${!d.revealed?action('reveal','Show one way through','text-button'):''}</div>${model(d)}${d.revealed?`<section class="facts-reveal"><h3 tabindex="-1" id="facts-reveal-title">One way through</h3><p>${splitText(d,true)}</p>${hearButton(splitText(d,true),'Hear this explanation')}</section>`:''}${correct?action('finish','Save this one','primary'):''}<div class="facts-leave">${action('skip','Skip for now','text-button')}<a class="text-button" href="#home">Take a break</a></div><details class="grownup-note"><summary>For grown-ups</summary>${d.model?'<p class="tiny">Opening the picture is recorded as support, even if it is closed or counted again.</p>':''}${d.revealed?'<p class="tiny">The shown answer and explanation stay recorded as support.</p>':''}${correct?'<p class="tiny">A correct number does not show which method was used. The method is optional.</p>':''}<p class="tiny facts-encounter">${d.ownPrior?'This ordered fact was opened earlier in this garden.':d.legacyKnown?'A related factor pair was encountered elsewhere in the app.':'This ordered fact has no earlier opening recorded in this garden.'}${d.priorExposureUnknown?' Earlier encounters outside this garden may not have been recorded.':''} All activity here is practice. None of it counts as fresh assessment evidence.</p></details></article></div>`;
}
export function factsPage(state,slug){return slug==='play'?practice(state):matrix(state);}
export function factsNotes(state){
 const f=state.facts;if(!f)return '<section class="panel facts-notes"><h2>Multiplication garden practice</h2><p>No practice observations yet.</p><a href="#facts">Open all multiplication facts</a></section>';
 const summaries=factsSummary(state).filter(c=>c.seen||c.records.length),x=f.current,d=currentFact(state);
 return `<section class="panel facts-notes"><h2>Multiplication garden practice</h2><p>Only an explicitly reported method is shown. “Reported recall” requires a correct first attempt, an explicit recalled report, and no support/model/reveal for that question. It is not mastery or proof of lasting fluency. Reversed facts retain separate observations.</p><p class="tiny">The latest ${factsRecordLimit} observations are retained, with up to 30 attempts per question; older records may be absent. Ordered encounter flags remain until reset. Distinct days below describe retained observations only, not an exhaustive history. All garden activity is practice; no baseline record is rewritten.</p>${x&&!x.finished&&d?`<aside class="facts-waiting"><h3>A practice draft is waiting</h3><p>${d.a} × ${d.b}; ${d.attempts.length} attempts; ${d.supported?'support used':'no support recorded'}; ${d.method?esc(methodLabels[d.method]):'method unobserved'}.</p><a href="#facts/play">Return to this draft</a></aside>`:''}<details class="facts-observation-list"><summary>Ordered facts with retained encounters (${summaries.length} of 144)</summary>${summaries.map(c=>`<details class="facts-fact-note"><summary>${c.a} × ${c.b}: ${esc(resultLabel(c.latest))}</summary><p>${c.records.length} retained observations across ${c.days.length} distinct ${c.days.length===1?'day':'days'}${c.days.length?': '+c.days.map(esc).join(', '):''}. ${!c.records.length?'No answer observation retained; knowledge remains unknown.':''}</p>${c.records.map(r=>`<article class="facts-attempt-note"><h4>${esc(r.day||'Day not recorded')} · ${esc(r.visitId)} · ${esc(resultLabel(r))}</h4><p>Answers: ${r.attempts.length?r.attempts.map(t=>`${t.value} (${t.correct?'matches':'does not match'}, ${esc(t.day||'day not recorded')}; ${t.method?esc(methodLabels[t.method]):'method unobserved'}${t.supported?'; support':''})`).join(' / '):'None'}.</p><p>Question method: ${r.method?esc(methodLabels[r.method]):'unobserved'}. Support: ${r.supported?'used':'not recorded'}; model ${r.model?'opened':'not opened'}; explanation ${r.revealed?'opened':'not opened'}. ${r.status==='skipped'?'Explicitly left for now.':r.status==='changed'?'Closed when another practice visit was chosen.':''}</p><p>Earlier encounters: ${r.ownPrior?'this ordered fact opened in the garden; ':''}${r.legacyKnown?'related factor pair recorded elsewhere; ':''}${r.priorExposureUnknown?'outside history partly unknown.':!r.ownPrior&&!r.legacyKnown?'none recorded.':''}</p></article>`).join('')}</details>`).join('')||'<p>No ordered facts encountered yet.</p>'}</details><a href="#facts">Return to all 144 facts</a></section>`;
}
export function bindFacts(state,{save,render,focus,exposeFacts}){
 const root=document.querySelector('[data-facts-view]');if(!root)return;
 const expose=()=>{const pairs=factPairsShown(state);if(pairs.length)exposeFacts(pairs);};
 const redraw=selector=>{save();render();if(selector)focus(selector);};
 const go=()=>{expose();save();if(location.hash==='#facts/play'){render();focus('#facts-question-title');}else location.hash='#facts/play';};
 root.querySelectorAll('[data-facts-pair]').forEach(el=>el.addEventListener('click',()=>{const [a,b]=el.dataset.factsPair.split(',').map(Number);if(startFact(state,a,b))go();}));
 root.querySelector('[data-facts-row]')?.addEventListener('change',event=>{setFactsRow(state,Number(event.target.value));redraw('#facts-row');});
 root.querySelector('.facts-table')?.addEventListener('keydown',event=>{
  const el=event.target.closest('[data-facts-pair]');if(!el||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key))return;
  event.preventDefault();let [a,b]=el.dataset.factsPair.split(',').map(Number);if(event.key==='ArrowLeft')b--;if(event.key==='ArrowRight')b++;if(event.key==='ArrowUp')a--;if(event.key==='ArrowDown')a++;if(event.key==='Home')b=1;if(event.key==='End')b=12;
  const target=root.querySelector(`.facts-table [data-facts-pair="${Math.max(1,Math.min(12,a))},${Math.max(1,Math.min(12,b))}"]`);target?.focus();target?.scrollIntoView({block:'nearest',inline:'nearest'});
 });
 const input=root.querySelector('#facts-answer');input?.addEventListener('input',()=>{const d=currentFact(state);if(d&&!d.recorded){d.input=input.value.slice(0,3);save();}});
 root.querySelector('[data-facts-answer-form]')?.addEventListener('submit',event=>{event.preventDefault();const value=numericAnswer(input.value);if(!Number.isSafeInteger(value)||value<0||value>999){root.querySelector('[data-facts-error]').textContent='Use a whole number from 0 to 999, or choose “Skip for now.”';input.focus();return;}submitFact(state,value);redraw('#facts-feedback');});
 root.querySelectorAll('[data-facts-method]').forEach(el=>el.addEventListener('click',()=>{setFactMethod(state,el.dataset.factsMethod);redraw(`[data-facts-method="${el.dataset.factsMethod}"]`);}));
 root.querySelectorAll('[data-facts-action]').forEach(el=>el.addEventListener('click',()=>{
  const id=el.dataset.factsAction;
  if(id==='mixed'){if(startFactsMix(state))go();return;}
  if(id==='array'||id==='groups'){showFactModel(state,id);expose();redraw('#facts-model-title');return;}
  if(id==='reveal'){revealFact(state);expose();redraw('#facts-reveal-title');return;}
  if(id==='step'||id==='recount'){stepFactModel(state,id==='step'?1:'reset');redraw('#facts-model-title');return;}
  if(id==='clear-method'){setFactMethod(state,null);redraw('#facts-question-title');return;}
  if(id==='finish'||id==='skip'){finishFact(state,id==='skip'?'skipped':'recorded');redraw('#facts-question-title');return;}
  if(id==='next'){advanceFacts(state);expose();redraw('#facts-question-title');}
 }));
}
